#!/usr/bin/env python3
import sys
import numpy as np


def solve(S: str):
    w = {'SUN':7, 'MON':6, 'TUE':5, 'WED':4, 'THU':3, 'FRI':2, 'SAT':1}
    print(w[S])
    return


